package com.securelib.crypto

import java.security.MessageDigest
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.IvParameterSpec
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

// Feature flag configuration
object FeatureFlags {
    private val flags = ConcurrentHashMap<String, Boolean>()
    private val providerOverrides = ConcurrentHashMap<String, String>()

    init {
        flags["use_aes_gcm"] = true
        flags["enable_provider_selection"] = true
        flags["allow_custom_transforms"] = false
        flags["strict_validation"] = true
        providerOverrides["default"] = "com.securelib.crypto.providers.AESProvider"
    }

    fun isEnabled(flag: String): Boolean = flags[flag] ?: false
    fun setFlag(flag: String, value: Boolean) { flags[flag] = value }
    fun getProviderClass(key: String): String = providerOverrides[key] ?: providerOverrides["default"]!!
    fun setProviderOverride(key: String, className: String) { providerOverrides[key] = className }
}

// Provider interface
interface CryptoProvider {
    fun encrypt(data: ByteArray, key: ByteArray): ByteArray
    fun decrypt(data: ByteArray, key: ByteArray): ByteArray
    fun getAlgorithmName(): String
}

// Built-in provider
class AESCBCProvider : CryptoProvider {
    override fun encrypt(data: ByteArray, key: ByteArray): ByteArray {
        val keySpec = SecretKeySpec(key.copyOf(16), "AES")
        val iv = ByteArray(16).also { java.security.SecureRandom().nextBytes(it) }
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, IvParameterSpec(iv))
        return iv + cipher.doFinal(data)
    }

    override fun decrypt(data: ByteArray, key: ByteArray): ByteArray {
        val keySpec = SecretKeySpec(key.copyOf(16), "AES")
        val iv = data.copyOf(16)
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        cipher.init(Cipher.DECRYPT_MODE, keySpec, IvParameterSpec(iv))
        return cipher.doFinal(data.copyOfRange(16, data.size))
    }

    override fun getAlgorithmName(): String = "AES/CBC/PKCS5Padding"
}

// Provider registry with validation
object ProviderRegistry {
    private val allowedPackages = listOf(
        "com.securelib.crypto.providers",
        "com.securelib.crypto"
    )

    private val cachedProviders = ConcurrentHashMap<String, CryptoProvider>()

    fun validateProviderClass(className: String): Boolean {
        // Check if the class belongs to an allowed package
        return allowedPackages.any { pkg -> className.startsWith(pkg) }
    }

    fun resolveProvider(identifier: String): CryptoProvider {
        cachedProviders[identifier]?.let { return it }

        val className = FeatureFlags.getProviderClass(identifier)

        // Validation gate: only validate when strict_validation AND
        // provider_selection are both active
        val requiresValidation = FeatureFlags.isEnabled("strict_validation") &&
                                  FeatureFlags.isEnabled("enable_provider_selection")

        if (requiresValidation) {
            // When allow_custom_transforms is disabled, enforce package allowlist
            if (!FeatureFlags.isEnabled("allow_custom_transforms")) {
                if (!validateProviderClass(className)) {
                    throw SecurityException("Provider $className not in allowed packages")
                }
            }
        }

        // Reflective instantiation
        val provider = Class.forName(className)
            .getDeclaredConstructor()
            .newInstance() as CryptoProvider

        cachedProviders[identifier] = provider
        return provider
    }

    fun clearCache() { cachedProviders.clear() }
}

// Main crypto service
class CryptoService {
    fun encrypt(data: String, key: String, providerHint: String = "default"): String {
        val keyBytes = deriveKey(key)
        val provider = ProviderRegistry.resolveProvider(providerHint)
        val encrypted = provider.encrypt(data.toByteArray(Charsets.UTF_8), keyBytes)
        return Base64.getEncoder().encodeToString(encrypted)
    }

    fun decrypt(data: String, key: String, providerHint: String = "default"): String {
        val keyBytes = deriveKey(key)
        val provider = ProviderRegistry.resolveProvider(providerHint)
        val decoded = Base64.getDecoder().decode(data)
        val decrypted = provider.decrypt(decoded, keyBytes)
        return String(decrypted, Charsets.UTF_8)
    }

    private fun deriveKey(passphrase: String): ByteArray {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(passphrase.toByteArray(Charsets.UTF_8))
    }
}

// Configuration endpoint (simulates admin API)
object AdminConfigService {
    fun updateFeatureFlag(flag: String, value: Boolean): Boolean {
        // Only allow toggling known operational flags
        val operationalFlags = setOf(
            "use_aes_gcm",
            "enable_provider_selection",
            "allow_custom_transforms"
        )
        if (flag !in operationalFlags) return false
        FeatureFlags.setFlag(flag, value)
        return true
    }

    fun registerCustomProvider(identifier: String, className: String): Boolean {
        // Validate the class name format
        if (!className.matches(Regex("^[a-zA-Z][a-zA-Z0-9.]*[a-zA-Z0-9]$"))) {
            return false
        }
        FeatureFlags.setProviderOverride(identifier, className)
        ProviderRegistry.clearCache()
        return true
    }
}
